CREATE SCHEMA match_identity_private;
REVOKE ALL ON SCHEMA match_identity_private FROM PUBLIC,anon,authenticated;
CREATE FUNCTION match_identity_private.guard_identity() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=''
AS $body$
DECLARE col text;
BEGIN
 IF current_user IN ('anon','authenticated') THEN
  FOREACH col IN ARRAY TG_ARGV LOOP
   IF to_jsonb(NEW)->col IS DISTINCT FROM to_jsonb(OLD)->col THEN
    RAISE EXCEPTION '試合データのID・親参照は変更できません' USING ERRCODE='42501';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $body$;
REVOKE ALL ON FUNCTION match_identity_private.guard_identity() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.rounds FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id','event_id');
CREATE POLICY rls08_rounds_delete ON public.rounds FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.events e WHERE e.id=rounds.event_id AND (auth.uid() IS NOT NULL AND NOT coalesce(e.is_deleted,false) AND (
 public.is_super_user() OR (e.club_id IS NULL AND e.created_by_auth_user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=e.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))
 OR (e.event_mode='team' AND public.can_manage_friendly_team_event_by_sides(e.id,e.created_by_auth_user_id))
))));
CREATE POLICY rls08_rounds_select_compat ON public.rounds FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY rls08_rounds_insert_compat ON public.rounds FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY rls08_rounds_update_compat ON public.rounds FOR UPDATE TO anon,authenticated USING(true) WITH CHECK(true);
DROP POLICY dev_all_rounds ON public.rounds;
REVOKE TRUNCATE ON public.rounds FROM anon,authenticated;
CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.matches FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id','event_id','round_id');
CREATE POLICY rls08_matches_delete ON public.matches FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.events e WHERE e.id=matches.event_id AND (auth.uid() IS NOT NULL AND NOT coalesce(e.is_deleted,false) AND (
 public.is_super_user() OR (e.club_id IS NULL AND e.created_by_auth_user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=e.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))
 OR (e.event_mode='team' AND public.can_manage_friendly_team_event_by_sides(e.id,e.created_by_auth_user_id))
))));
CREATE POLICY rls08_matches_select_compat ON public.matches FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY rls08_matches_insert_compat ON public.matches FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY rls08_matches_update_compat ON public.matches FOR UPDATE TO anon,authenticated USING(true) WITH CHECK(true);
DROP POLICY dev_all_matches ON public.matches;
REVOKE TRUNCATE ON public.matches FROM anon,authenticated;
CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.match_players FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id','match_id','participant_id');
CREATE POLICY rls08_match_players_delete ON public.match_players FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.matches m JOIN public.events e ON e.id=m.event_id WHERE m.id=match_players.match_id AND (auth.uid() IS NOT NULL AND NOT coalesce(e.is_deleted,false) AND (
 public.is_super_user() OR (e.club_id IS NULL AND e.created_by_auth_user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=e.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))
 OR (e.event_mode='team' AND public.can_manage_friendly_team_event_by_sides(e.id,e.created_by_auth_user_id))
))));
CREATE POLICY rls08_match_players_select_compat ON public.match_players FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY rls08_match_players_insert_compat ON public.match_players FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY rls08_match_players_update_compat ON public.match_players FOR UPDATE TO anon,authenticated USING(true) WITH CHECK(true);
DROP POLICY dev_all_match_players ON public.match_players;
REVOKE TRUNCATE ON public.match_players FROM anon,authenticated;
CREATE TRIGGER guard_match_identity BEFORE UPDATE ON public.match_results FOR EACH ROW EXECUTE FUNCTION match_identity_private.guard_identity('id','match_id');
CREATE POLICY rls08_match_results_delete ON public.match_results FOR DELETE TO authenticated USING(EXISTS(SELECT 1 FROM public.matches m JOIN public.events e ON e.id=m.event_id WHERE m.id=match_results.match_id AND (auth.uid() IS NOT NULL AND NOT coalesce(e.is_deleted,false) AND (
 public.is_super_user() OR (e.club_id IS NULL AND e.created_by_auth_user_id=auth.uid())
 OR EXISTS(SELECT 1 FROM public.club_members cm LEFT JOIN public.player_profiles pp ON pp.id=cm.player_profile_id
 WHERE cm.club_id=e.club_id AND cm.is_active AND (cm.profile_id=auth.uid() OR pp.linked_auth_user_id=auth.uid()))
 OR (e.event_mode='team' AND public.can_manage_friendly_team_event_by_sides(e.id,e.created_by_auth_user_id))
))));
CREATE POLICY rls08_match_results_select_compat ON public.match_results FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY rls08_match_results_insert_compat ON public.match_results FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY rls08_match_results_update_compat ON public.match_results FOR UPDATE TO anon,authenticated USING(true) WITH CHECK(true);
DROP POLICY dev_all_match_results ON public.match_results;
REVOKE TRUNCATE ON public.match_results FROM anon,authenticated;
DROP POLICY rls07_participants_delete_compat ON public.event_participants;
REVOKE DELETE ON public.event_participants FROM anon,authenticated;
DO $guard$ DECLARE r text; t text; BEGIN
 FOREACH r IN ARRAY ARRAY['anon','authenticated'] LOOP
  FOREACH t IN ARRAY ARRAY['rounds','matches','match_players','match_results'] LOOP
   IF has_table_privilege(r,'public.'||t,'TRUNCATE') THEN RAISE EXCEPTION 'Inherited TRUNCATE remains'; END IF;
  END LOOP;
  IF has_table_privilege(r,'public.event_participants','DELETE') THEN RAISE EXCEPTION 'Inherited participant DELETE remains'; END IF;
 END LOOP;
END $guard$;
COMMIT;
